import {Mode} from './mode-base.js';
import {THREE,box,cylinder,ring,moveActor,distance,label} from './world.js';
import {segmentBlocked,slideMove,routeTo} from './venues.js';
import {clamp,sweptDistance,ringTarget,chalk} from './ball-physics.js';

export class Pampanaa extends Mode{
 constructor(ctx){super(ctx);this.solids=this.venue.solids;this.world.setCamera([-6,2.5,18,-6,1,8]);this.world.cameraKind='neighbourhood';this.heading=Math.PI;this.pitch=0;this.you=this.player(-6,14);this.you.rotation.y=this.heading;this.players=[this.you];this.alive=[true,true,true,true,true,true];this.names=['YOU','KOJO','ESI','NII','AMA','KOFI'];this.cool=0;this.hideCount=5;this.phase='hide';this.stamina=1;this.aimed=-1;this.gesture='hand';this.sticks=[];this.pops=[];this.points=[[-6,14],[-14,-4],[7,-14],[14,8],[-3,-6],[6,6],[-5,1],[6,-3],[0,6],[14,-13],[-14,12]];this.setActions([{id:'shoot',label:'Pɛw! Shoot',key:'Space'},{id:'left',label:'Look left',key:'Q'},{id:'right',label:'Look right',key:'E'},{id:'sprint',label:'Sprint',key:'Shift',hold:true},{id:'gesture',label:'Hand / stick',key:'R'}]);
  for(let i=1;i<6;i++){const p=this.player(...this.points[i],i%2?0x487e78:0xa18b4c);p.userData={...p.userData,id:i,alert:0,cool:1+i*.2,route:[],destination:this.points[(i+3)%this.points.length],think:0,heard:null};this.players.push(p);}
  this.players.forEach((p,i)=>{p.userData.pick=i;p.traverse(o=>{if(o.isMesh)o.userData.pick=i;});const stick=cylinder(.022,.029,.72,0x897254,0,0,0,this.root,8);this.sticks.push(stick);});
  this.reticle=ringTarget(this.root);this.reticle.visible=false;this.note('Hide in the neighbourhood. Drag the scene or use Q/E to look. Point and call Pɛw! when a rival is in view. Last player wins.');
 }
 drag(dx,dy){this.heading-=dx*.007;this.pitch=clamp(this.pitch+dy*.003,-.45,.4);}
 hit({point,id}){if(typeof id==='number'&&this.alive[id]&&id!==0){const p=this.players[id].position;this.heading=Math.atan2(p.x-this.you.position.x,p.z-this.you.position.z);}else if(point)this.heading=Math.atan2(point.x-this.you.position.x,point.z-this.you.position.z);}
 canSee(i,j,range=13,fov=.65){if(!this.alive[i]||!this.alive[j]||i===j)return false;const a=this.players[i],b=this.players[j],d=distance(a,b);if(d>range)return false;const direction=new THREE.Vector3(b.position.x-a.position.x,0,b.position.z-a.position.z).normalize(),forward=new THREE.Vector3(Math.sin(a.rotation.y),0,Math.cos(a.rotation.y));return direction.dot(forward)>fov&&!segmentBlocked(a.position,b.position,this.solids,.02);}
 action(id){if(id==='left'){this.heading+=Math.PI/7;return;}if(id==='right'){this.heading-=Math.PI/7;return;}if(id==='gesture'){this.gesture=this.gesture==='hand'?'stick':'hand';this.note(this.gesture==='hand'?'Point with your hand and make the call.':'Point the pretend stick and make the call.');return;}if(id!=='shoot'||this.phase!=='play'||this.cool>0||!this.alive[0])return;this.cool=.8;this.you.userData.pose='point';this.poseUntil=this.age+.45;const candidates=this.players.map((p,i)=>i).filter(i=>this.canSee(0,i,13,.97)).sort((a,b)=>distance(this.you,this.players[a])-distance(this.you,this.players[b]));this.call(0);if(candidates.length)this.eliminate(candidates[0],0);else this.note('Pɛw! No clear target. Walls block the call — line up your view.');}
 call(i){const p=this.players[i];p.userData.pose='point';const pop=label('Pɛw!','#e5d7aa',.2,this.root);pop.position.copy(p.position).add(new THREE.Vector3(0,2.1,0));this.pops.push({pop,life:.7});this.ui.sound('mouth');for(let j=1;j<this.players.length;j++)if(j!==i&&this.alive[j]&&distance(p,this.players[j])<10){this.players[j].userData.heard=p.position.clone();this.players[j].userData.think=0;}}
 eliminate(i,by){if(!this.alive[i])return false;this.alive[i]=false;this.players[i].visible=false;this.sticks[i].visible=false;this.score+=by===0?1:0;const remaining=this.alive.filter(Boolean).length;this.note(`${this.names[by]} called ${this.names[i]} out. ${remaining} players remain.`);if(i===0){this.phase='over';this.finish('CALLED OUT',`${this.names[by]} saw you first with a clear view. ${remaining} players remained.`,false);}else if(remaining===1){this.phase='over';this.finish('LAST PLAYER STANDING',`You stayed in the game. ${this.score} rivals called out by you.`);}return true;}
 update(dt){this.cool=Math.max(0,this.cool-dt);this.status(`${this.alive.filter(Boolean).length} PLAYERS IN`,this.phase==='hide'?`HIDE · ${Math.max(0,Math.ceil(this.hideCount-this.time))}`:this.aimed>=0?'IN SIGHT: '+this.names[this.aimed]:'LISTEN. LOOK. KEEP COVER.');
  const raw=this.input.vector(),forward=new THREE.Vector3(Math.sin(this.heading),0,Math.cos(this.heading)),right=new THREE.Vector3(-forward.z,0,forward.x);const velocity=right.multiplyScalar(raw.x).addScaledVector(forward,-raw.z);const sprint=this.input.sprint&&this.stamina>.08&&velocity.length()>.1;this.stamina=clamp(this.stamina+(sprint?-.2:.14)*dt,0,1);velocity.multiplyScalar(sprint?6.5:3.8);if(!this.networked){slideMove(this.you.position,velocity,dt,this.solids);this.you.rotation.y=this.heading;}this.you.userData.run=velocity.length()/6;let cameraDistance=2.4;while(cameraDistance>.35&&segmentBlocked(this.you.position,{x:this.you.position.x-forward.x*cameraDistance,z:this.you.position.z-forward.z*cameraDistance},this.solids,.12))cameraDistance-=.2;this.world.desired?.set(this.you.position.x-forward.x*cameraDistance,2.2,this.you.position.z-forward.z*cameraDistance);this.world.targetLook?.set(this.you.position.x+forward.x*7,1.5+this.pitch*6,this.you.position.z+forward.z*7);this.world.cameraKind='neighbourhood';this.ui.energy?.(this.stamina,0,'YOU');
  if(this.phase==='hide'&&this.time>=this.hideCount){this.phase='play';this.note('Go! Clear sight and a mouth-made call. One hit eliminates a player.');}
  this.aimed=this.players.findIndex((p,i)=>this.canSee(0,i,13,.97));this.ui.context?.({shoot:this.aimed>=0?'Pɛw! '+this.names[this.aimed]:'Pɛw! Shoot'});
  this.sticks.forEach((s,i)=>{const p=this.players[i],h=p.rotation.y;s.visible=this.alive[i]&&(i>0||this.gesture==='stick');s.position.set(p.position.x+Math.sin(h)*.5,1.25,p.position.z+Math.cos(h)*.5);s.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),new THREE.Vector3(Math.sin(h),0,Math.cos(h)));});
  for(let i=1;i<this.players.length;i++){if(!this.alive[i]||this.networked)continue;const p=this.players[i],u=p.userData;u.cool=Math.max(0,u.cool-dt);u.think-=dt;
   const visible=this.players.map((_,j)=>j).filter(j=>this.canSee(i,j,12,.6)).sort((a,b)=>distance(p,this.players[a])-distance(p,this.players[b]));const target=visible[0];
   if(target!==undefined&&this.phase==='play'){const q=this.players[target];p.rotation.y=Math.atan2(q.position.x-p.position.x,q.position.z-p.position.z);u.alert+=dt;p.userData.run=0;p.userData.pose='point';if(u.alert>(target===0?1.25:.8)*this.difficultyTuning.window&&u.cool<=0){this.call(i);this.eliminate(target,i);u.cool=1.8;u.alert=0;if(this.done)return;}}
   else{u.alert=Math.max(0,u.alert-dt*2);u.pose='idle';if(u.think<=0){u.think=2+Math.random()*2;const waypoint=this.points[Math.floor(Math.random()*this.points.length)];const dest=u.heard||new THREE.Vector3(waypoint[0],0,waypoint[1]);u.heard=null;u.route=routeTo(p.position,dest,this.solids);}
    const targetPoint=u.route[0];if(targetPoint){const dir=targetPoint.clone().sub(p.position);dir.y=0;if(dir.length()<.3)u.route.shift();else{dir.normalize().multiplyScalar((this.phase==='hide'?3.4:2.2)*this.difficultyTuning.speed);slideMove(p.position,dir,dt,this.solids);p.rotation.y=Math.atan2(dir.x,dir.z);p.userData.run=.5;}}else{p.userData.run=0;p.rotation.y+=dt*.55;}}
  }
  if(this.age>(this.poseUntil||0))this.you.userData.pose='idle';for(const item of this.pops){item.life-=dt;item.pop.position.y+=dt*.2;item.pop.material.opacity=Math.max(0,item.life/.7);}this.pops=this.pops.filter(item=>{if(item.life>0)return true;this.root.remove(item.pop);item.pop.material.map.dispose();item.pop.material.dispose();return false;});
 }
}

export class RubberBand extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([.7,1.65,5.5,0,1.05,-4]);this.world.aimPlane=new THREE.Plane(new THREE.Vector3(0,0,1),4.1);this.you=this.player(-.55,3.2);this.you.rotation.y=Math.PI;this.you.userData.pose='band';this.rival=this.player(2.5,2,0x3c7882);this.targetStick=cylinder(.018,.024,.38,0xc5ae75,0,1.12,-3.92,this.root,10);this.targetStick.rotation.x=Math.PI/2;this.targetTip=new THREE.Vector3(0,1.12,-3.72);const nail=cylinder(.012,.012,.16,0x544d42,0,1.12,-4.02,this.root,8);nail.rotation.x=Math.PI/2;const patch=box(.65,.55,.015,0xa2967e,0,1.1,-4.125,this.root);patch.material.transparent=true;patch.material.opacity=.25;
  this.reticle=ringTarget(this.root);this.reticle.scale.setScalar(.32);this.reticle.position.copy(this.targetTip);this.band=new THREE.Mesh(new THREE.TorusGeometry(.055,.006,6,28),new THREE.MeshStandardMaterial({color:0xc2a462,roughness:.9}));this.root.add(this.band);this.v=new THREE.Vector3();this.origin=new THREE.Vector3(0,1.12,2.8);this.aimX=0;this.aimY=1.12;this.scores=[0,0];this.shots=[0,0];this.turn=0;this.phase='aim';this.charge=null;this.prepare();chalk(this.root,0,3.2,3,.04);this.note('Tyre: the wall-stick game. Aim the band at the small projecting stick. Hold Pull, release. Six bands each.');}
 prepare(){this.phase='aim';this.time=0;this.charge=null;this.band.visible=true;this.band.position.copy(this.origin);this.band.scale.set(1,1,1);this.band.rotation.set(0,0,0);this.targetStick.rotation.z=0;this.setActions(this.turn?[{id:'wait',label:'Their band',key:'Space',disabled:true}]:[{id:'release',label:'Pull / release',key:'Space',charge:true},{id:'reset',label:'Centre aim',key:'E'}]);}
 hold(id){if(!this.turn&&this.phase==='aim'&&id==='release')this.charge=this.age;}
 hit({point}){if((!this.turn||this.networked)&&this.phase==='aim'){this.aimX=clamp(point.x,-1.2,1.2);this.aimY=clamp(point.y,.4,2);}}
 action(id){if((this.turn&&!this.networked)||this.phase!=='aim')return;if(id==='reset'){this.aimX=0;this.aimY=1.12;return;}const pull=this.charge===null?.6:clamp((this.age-this.charge)/1.2,.1,1);this.release(this.aimX,this.aimY,pull);this.charge=null;}
 release(x,y,pull){this.phase='flight';this.time=0;const speed=15+pull*20,range=this.origin.z-this.targetTip.z,flight=range/speed;this.v.set(x/flight,(y-this.origin.y)/flight+1.2,-speed);this.band.position.copy(this.origin);this.band.scale.set(1,1,1);this.ui.sound('band');this.you.userData.pose='point';}
 resolve(hit){if(this.phase!=='flight')return;this.shots[this.turn]++;if(hit){this.scores[this.turn]++;this.targetStick.rotation.z=.22;}this.phase='result';this.time=0;this.note(hit?'The band hit the stick. One point.':'Missed the stick. Adjust aim and pull.');this.ui.sound(hit?'point':'stone');}
 update(dt){const pull=this.charge===null?0:clamp((this.age-this.charge)/1.2,0,1);this.status(`YOU ${this.scores[0]} — ${this.scores[1]} THEM`,`${this.turn?'THEIR':'YOUR'} BAND ${Math.min(6,this.shots[this.turn]+1)} / 6 · ${Math.round(pull*100)}% PULL`);this.reticle.visible=(!this.turn||this.networked)&&this.phase==='aim';if(this.phase==='aim'){if(!this.turn||this.networked){const v=this.input.vector();this.aimX=clamp(this.aimX+v.x*dt*.5,-1.2,1.2);this.aimY=clamp(this.aimY-v.z*dt*.4,.4,2);this.reticle.position.set(this.aimX,this.aimY,-3.7);this.you.userData.bandPull=pull;this.you.userData.pose='band';this.band.scale.set(1,1+pull*3,1);this.band.position.copy(this.origin);this.band.position.z+=pull*.25;this.ui.power?.(pull);}else if(this.time>1.5)this.release((Math.random()-.5)*.18*this.difficultyTuning.error,1.12+(Math.random()-.5)*.18*this.difficultyTuning.error,.5+Math.random()*.4);}else if(this.phase==='flight'){const before=this.band.position.clone();this.v.y-=9.81*dt;this.band.position.addScaledVector(this.v,dt);this.band.rotation.x+=dt*18;this.band.rotation.z+=dt*6;const tip=this.targetTip.clone(),end=new THREE.Vector3(0,1.12,-4.1);if(sweptDistance(before,this.band.position,tip)<.075||sweptDistance(before,this.band.position,end)<.075)this.resolve(true);else if(this.band.position.z<-4.1||this.band.position.y<0||this.time>1)this.resolve(false);}else if(this.time>1.5){if(this.shots.every(n=>n>=6)){this.score=this.scores[0];this.finish(this.score===this.scores[1]?'SAME NUMBER OF HITS':this.score>this.scores[1]?'YOUR AIM WINS':'THEIR AIM WINS',`${this.score}–${this.scores[1]} stick hits from six bands each.`,this.score>=this.scores[1]);}else{this.turn=1-this.turn;this.prepare();}}}
}
